const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let p = 0;

const N = parseInt(data[p++], 10);
const M = parseInt(data[p++], 10);

class Fenwick {
  constructor(n) {
    this.n = n;
    this.bit = new Float64Array(n + 2);
  }

  add(i, v) {
    const n = this.n;
    const bit = this.bit;
    for (; i <= n; i += i & -i) {
      bit[i] += v;
    }
  }

  sum(i) {
    const bit = this.bit;
    let s = 0;
    for (; i > 0; i -= i & -i) {
      s += bit[i];
    }
    return s;
  }

  rangeAdd(l, r, v) {
    this.add(l, v);
    if (r + 1 <= this.n) {
      this.add(r + 1, -v);
    }
  }
}

const bitA = new Fenwick(N);
const bitB = new Fenwick(N);
const out = [];

for (let q = 0; q < M; q++) {
  const type = parseInt(data[p++], 10);

  if (type === 3) {
    const i = parseInt(data[p++], 10);
    const ans = bitA.sum(i) * i + bitB.sum(i);
    out.push(String(ans));
  } else {
    const i = parseInt(data[p++], 10);
    const V = parseInt(data[p++], 10);

    if (type === 1) {
      const l = i;
      const r = Math.min(N, i + V - 1);
      bitA.rangeAdd(l, r, -1);
      bitB.rangeAdd(l, r, V + i);
    } else {
      const l = Math.max(1, i - V + 1);
      const r = i;
      bitA.rangeAdd(l, r, 1);
      bitB.rangeAdd(l, r, V - i);
    }
  }
}

process.stdout.write(out.join('\n'));
